sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var consumerID = g_form.getValue("user_id");
	//g_form.addErrorMessage(consumerID);
   if(newValue!="Basic"){
        var ga1 = new GlideAjax("CreateCarWashEntitlement");
        ga1.addParam('sysparm_name', 'createEntitlement');
        ga1.addParam('sysparm_plan', newValue);
        ga1.addParam('sysparm_consumer', consumerID);

        ga1.getXMLAnswer(function(response1) {
            // Only after first is successful, trigger the second AJAX
            if (response1 == "created") {
                // Inform the user
                g_form.addInfoMessage("Car Wash Entitlement created for " + newValue + " plan.");

                // Second AJAX call → Service Entitlement
				var ga2 = new GlideAjax("ServiceCarWashEntitlement");
                ga2.addParam('sysparm_name', 'servicecreateEntitlement');
                ga2.addParam('sysparm_plan1', newValue);
                ga2.addParam('sysparm_consumer1', consumerID);

                ga2.getXMLAnswer(function(response2) {
                    if (response2 == "created") {
                        g_form.addInfoMessage("Service Entitlement also created for " + newValue + " plan.");
                    } else {
                        g_form.addErrorMessage("Failed to create Service Entitlement: " + response2);
                    }
                });

            } else {
                g_form.addErrorMessage("Failed to create Car Wash Entitlement: " + response1);
            }
        });

    }
}
